import{z as B,x as E,o as t,c as d,q as A,j as o,D as s,d as r,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"FPGA LUT 与 CLB","description":"","frontmatter":{"title":"FPGA LUT 与 CLB","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fpga-lut-clb.md","filePath":"cs/fpga-lut-clb.md","lastUpdated":1791413859000}'),L={name:"cs/fpga-lut-clb.md"};function T(p,a,F,C,c,u){const l=E("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="fpga-lut-与-clb" tabindex="-1">FPGA LUT 与 CLB <a class="header-anchor" href="#fpga-lut-与-clb" aria-label="Permalink to &quot;FPGA LUT 与 CLB&quot;">​</a></h1><div class="epigraph"><p>查找表用 SRAM 存真值表，任意 $k$ 输入布尔函数一块 LUT 就够；可配置逻辑块再把 LUT、进位链与触发器捆在一起。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Kuon, Tessier, Rose, FPGA Architecture: Survey and Challenges, Found. Trends EDA 2008 整理</footer></div><p><a href="/cs/async-fifo-cdc">上一课</a>的 FIFO 与算术单元最终要落到某种硅结构上。ASIC 用标准单元库；FPGA 用<strong>可配置</strong>的 LUT 与 CLB（或 LAB）。缺口是：综合网表在 FPGA 上的<strong>基本砖</strong>是什么，而不是再讲综合算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/pla-rom">PLA</a> 用与或阵列；FPGA 主流是 SRAM LUT：6 输入 LUT 存 64 bit 真值表，实现任意 6 输入函数。CLB 含若干 LUT、FF、进位旁路（为加法器准备，对照 <a href="/cs/adder-cla">CLA</a> 的专用进位）。缺口不是「FPGA 比 ASIC 慢」的口号，而是映射目标：<code>assign y = a &amp; b</code> 变成 LUT 初始化值，<code>posedge</code> 变成 CLB 里的 FF。</p><p><span class="marginnote">直觉类比：LUT 是「查表器」不是「计算器」——一本 64 行的速查表，输入是页码，答案是出厂前就印好的。所以 6 输入函数再复杂，一块 LUT 都是一次查表搞定；反过来哪怕函数只是与门，也照样占一整本表。</span></p><p>DSP 块、块 RAM 是旁边的硬核，对应上一单元乘加与 FIFO RAM，本课点名，下一课布局才说怎么连。</p><h3 id="lut-不是「小型处理器」" tabindex="-1">LUT 不是「小型处理器」 <a class="header-anchor" href="#lut-不是「小型处理器」" aria-label="Permalink to &quot;LUT 不是「小型处理器」&quot;">​</a></h3><p>LUT 计算组合函数，没有程序计数器。把 LUT 理解成在芯片上跑解释器，会与后课 HLS 的「C 变成电路」混层。配置比特在上电时从闪存加载，那是静态结构，不是指令流。</p><p><span class="marginnote">顺着「配置易失」说一个常见现象：SRAM LUT 断电就忘，所以 FPGA 板卡上总挂着一片配置 Flash，每次上电重灌比特流——「FPGA 启动慢半拍」就是在这几毫秒到几百毫秒的加载里。</span></p><p><span class="marginnote">Harris 用 LUT 教 FPGA。Kuon/Tessier/Rose 综述架构。Xilinx/AMD CLB、Intel ALM 细节不同，本课钉 LUT+FF+进位链这一共同形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>综合：布尔映射到 LUT 覆盖（切函数到 \\(k\\) 输入）。打包：若干 LUT/FF 塞进同一 CLB 以共用布线口。进位链：专用连线实现快加，比用普通 LUT 进位短。配置 SRAM 易失，故需外部比特流——后课不必展开加载协议。</p>',13)),(t(),o(n,null,{default:s(()=>[i(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOL%5B%22%E5%B8%83%E5%B0%94%E5%87%BD%E6%95%B0%22%5D%20--%3E%20LUT%5B%22k-LUT%20%E7%9C%9F%E5%80%BC%E8%A1%A8%22%5D%0A%20%20LUT%20--%3E%20CLB%5B%22CLB%EF%BC%9ALUT%20%2B%20FF%20%2B%20%E8%BF%9B%E4%BD%8D%22%5D%0A%20%20CLB%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%B8%83%E5%B1%80%E5%B8%83%E7%BA%BF%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"异步 FIFO 的双口 RAM 优先映射到块 RAM，而不是 LUT RAM，除非深度很小。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[r("下一课布局布线把 CLB 放到二维阵列并连接开关盒。STA 用 FPGA 的延迟表，时钟用全局网络（对照 "),e("a",{href:"/cs/clock-skew-cts"},"CTS"),r("）。ASIC 标准单元课会对照：LUT 灵活、延迟与功耗通常差于硬连线标准单元。")],-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"为什么重要「进位走专用链」：64 位加法器若拆成 LUT 逐位算，进位要横穿几十个 CLB 的普通布线，延迟一路堆上去；专用进位链是相邻 CLB 之间的直达导线，像高速公路不走红绿灯。这就是 FPGA 上加法器几乎白拿进位链、只花少量 LUT 的原因。")],-1)),(t(),o(n,null,{default:s(()=>[i(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%20a%2Cb%2Cc%22%5D%20--%3E%20ADDR%5B%22%E6%8B%BC%E6%88%90%203%20%E4%BD%8D%E5%9C%B0%E5%9D%80%20abc%22%5D%0A%20%20CFG%5B%22%E7%BB%BC%E5%90%88%E5%99%A8%E5%86%99%E5%A5%BD%E7%9A%84%E7%9C%9F%E5%80%BC%E8%A1%A8%3A00011101%22%5D%20--%3E%20SRAM%5B%22LUT%20%E7%9A%84%208%20%E4%BD%8D%20SRAM%22%5D%0A%20%20ADDR%20--%3E%20SRAM%0A%20%20SRAM%20--%3E%20OUT%5B%22%E5%8F%96%E5%87%BA%E7%AC%AC%20abc%20%E5%8F%B7%E4%BD%8D%E4%BD%9C%E4%B8%BA%E8%BE%93%E5%87%BA%22%5D%0A%20%20EX%5B%22%E4%BE%8B%3A%E5%A4%9A%E6%95%B0%E5%87%BD%E6%95%B0%2C%E8%BE%93%E5%85%A5%20101%20%E2%86%92%20%E6%9F%A5%E7%AC%AC%205%20%E5%8F%B7%E4%BD%8D%20%3D%201%22%5D%20--%3E%20OUT%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不背某代 LUT 输入数，不把 eFPGA 嵌入式阵列写进主干。不讲光刻如何造 SRAM LUT。不把 FPGA 当「AI 加速器品牌」介绍。</p><p>后课默认：FPGA 组合逻辑的原子是 LUT，时序原子是 CLB 内 FF；硬核旁路乘加与 RAM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FPGA 用 LUT 存真值表，CLB 捆 LUT、FF、进位链。</li><li>综合映射到 LUT 覆盖，不是映射到 ASIC 标准单元。</li><li>下一课在阵列上放置这些块并布线。</li><li>出处：Harris and Harris；Kuon, Tessier, Rose, 2008。</li></ul>',5))])}const h=B(L,[["render",T]]);export{D as __pageData,h as default};
